-- Built-in ComfyUI workflow templates (phase 1). Standard-node placeholder
-- graphs with per-family dimensions and save prefixes; the builder injects
-- the LoRA stage and per-run prompts/seeds/dimensions. Validated custom
-- graphs replace them per triggerType as they land. Idempotent: fixed
-- primary keys with INSERT IGNORE.
INSERT IGNORE INTO comfyui_workflow (workflowId, name, description, workflowJson, triggerType, defaultParams, isBuiltIn) VALUES
('b0000000-0000-4000-8000-000000000001', 'Built-in character portrait', 'Phase 1 character portrait template. Standard node graph. The builder injects the LoRA stage and per-run prompts.', '{"1":{"class_type":"CheckpointLoaderSimple","inputs":{"ckpt_name":""}},"2":{"class_type":"CLIPTextEncode","inputs":{"text":"character portrait, detailed face, expressive eyes, masterpiece, best quality, highly detailed","clip":["1",1]}},"3":{"class_type":"CLIPTextEncode","inputs":{"text":"low quality, blurry, deformed, disfigured, bad anatomy, watermark, text","clip":["1",1]}},"4":{"class_type":"EmptyLatentImage","inputs":{"width":832,"height":1216,"batch_size":1}},"5":{"class_type":"KSampler","inputs":{"model":["1",0],"positive":["2",0],"negative":["3",0],"latent_image":["4",0],"seed":0,"steps":20,"cfg":7.0,"sampler_name":"euler_a","scheduler":"normal","denoise":1.0}},"6":{"class_type":"VAEDecode","inputs":{"samples":["5",0],"vae":["1",2]}},"7":{"class_type":"SaveImage","inputs":{"images":["6",0],"filename_prefix":"chatllm_portrait"}}}', 'character_portrait', '{"width":832,"height":1216,"steps":20,"cfg":7,"sampler":"euler_a","lora":""}', TRUE);

INSERT IGNORE INTO comfyui_workflow (workflowId, name, description, workflowJson, triggerType, defaultParams, isBuiltIn) VALUES
('b0000000-0000-4000-8000-000000000002', 'Built-in scene background', 'Phase 1 background template: environment only, no people in frame. Weather, time, and mood tags come from the conversation world state.', '{"1":{"class_type":"CheckpointLoaderSimple","inputs":{"ckpt_name":""}},"2":{"class_type":"CLIPTextEncode","inputs":{"text":"detailed landscape, environment art, atmospheric lighting, masterpiece, best quality, highly detailed","clip":["1",1]}},"3":{"class_type":"CLIPTextEncode","inputs":{"text":"low quality, blurry, people, person, human, character, figure, watermark, text","clip":["1",1]}},"4":{"class_type":"EmptyLatentImage","inputs":{"width":1344,"height":768,"batch_size":1}},"5":{"class_type":"KSampler","inputs":{"model":["1",0],"positive":["2",0],"negative":["3",0],"latent_image":["4",0],"seed":0,"steps":20,"cfg":7.0,"sampler_name":"euler_a","scheduler":"normal","denoise":1.0}},"6":{"class_type":"VAEDecode","inputs":{"samples":["5",0],"vae":["1",2]}},"7":{"class_type":"SaveImage","inputs":{"images":["6",0],"filename_prefix":"chatllm_scene"}}}', 'scene_change', '{"width":1344,"height":768,"steps":20,"cfg":7,"sampler":"euler_a","lora":""}', TRUE);
